// Daftar URL penting yang perlu di-check
const domain = $env.COMPANY_DOMAIN || 'example.com';
const criticalPages = [
  '/',
  '/products',
  '/pricing',
  '/contact',
  '/blog',
  '/about',
  '/login',
  '/signup'
];

const results = criticalPages.map(page => ({
  json: {
    url: `https://${domain}${page}`,
    page_type: page === '/' ? 'homepage' : page.replace('/', ''),
    is_critical: ['/', '/products', '/pricing', '/login'].includes(page)
  }
}));

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const response = item.json;
  const originalData = $node['Define Critical Pages'].json;

  const statusCode = response.statusCode || response.status || 0;
  const responseTime = response.responseTime || 0;
  const headers = response.headers || {};

  // Check SSL
  const hasSSL = originalData.url.startsWith('https');

  // Analyze issues
  const issues = [];

  if (statusCode >= 400) {
    issues.push({ type: 'error', message: `HTTP ${statusCode} error` });
  }
  if (responseTime > 3000) {
    issues.push({ type: 'warning', message: `Slow response: ${responseTime}ms` });
  }
  if (responseTime > 5000) {
    issues.push({ type: 'critical', message: `Very slow response: ${responseTime}ms` });
  }
  if (!headers['content-encoding']?.includes('gzip')) {
    issues.push({ type: 'info', message: 'No gzip compression detected' });
  }
  if (!headers['strict-transport-security']) {
    issues.push({ type: 'warning', message: 'Missing HSTS header' });
  }
  if (!headers['x-content-type-options']) {
    issues.push({ type: 'info', message: 'Missing X-Content-Type-Options header' });
  }

  const hasCriticalIssues = issues.some(i => i.type === 'critical' || i.type === 'error');

  results.push({
    json: {
      url: originalData.url,
      page_type: originalData.page_type,
      is_critical: originalData.is_critical,
      status_code: statusCode,
      response_time_ms: responseTime,
      has_ssl: hasSSL,
      issues: issues,
      issue_count: issues.length,
      has_critical_issues: hasCriticalIssues,
      checked_at: new Date().toISOString()
    }
  });
}

return results;

